select.where:
k.id != (SELECT internal_authentication_keys_id FROM instance LIMIT 1)

  AND (
  LOWER(k.name) LIKE #{nameOrDescription}
  OR

    LOWER(k.meta_data ->> '$.attributes.description') LIKE #{nameOrDescription}


    LOWER(k.meta_data::JSONB #>> '{attributes, description}') LIKE #{nameOrDescription}

  )


  AND LOWER(k.key_value) LIKE #{key}


  AND k.key_manager = #{keyManager}


  AND k.tenants_id = #{tenantId}


  AND expiration_instant >= #{expirationStart}


  AND expiration_instant <= #{expirationEnd}

mapper.select:
SELECT COUNT(*)
FROM authentication_keys AS k

  k.id != (SELECT internal_authentication_keys_id FROM instance LIMIT 1)

    AND (
    LOWER(k.name) LIKE #{nameOrDescription}
    OR

      LOWER(k.meta_data ->> '$.attributes.description') LIKE #{nameOrDescription}


      LOWER(k.meta_data::JSONB #>> '{attributes, description}') LIKE #{nameOrDescription}

    )


    AND LOWER(k.key_value) LIKE #{key}


    AND k.key_manager = #{keyManager}


    AND k.tenants_id = #{tenantId}


    AND expiration_instant >= #{expirationStart}


    AND expiration_instant <= #{expirationEnd}
